// V77: Supabase is now the live database source. The embedded V76 DATA remains
// as a fallback so the existing map can still open if the database is unavailable.
const SUPABASE_URL='https://mfkssylswtldncjuhwxu.supabase.co';
const SUPABASE_PUBLISHABLE_KEY='sb_publishable_L_7622Z8TFbHnyBFmXkVJA__1crEGky';
const supabaseClient=(window.supabase&&window.supabase.createClient)
  ? window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY)
  : null;
window.supabaseClient=supabaseClient;
let SUPABASE_CONNECTED_V77=false;

function makeFeatureFromSupabaseV77(row){
  const {longitude,latitude,...props}=row;
  const lon=Number(longitude), lat=Number(latitude);
  return {
    type:'Feature',
    properties:props,
    geometry:{type:'Point',coordinates:[lon,lat]}
  };
}

async function loadSupabasePokokV77(){
  if(!supabaseClient) throw new Error('Supabase client tidak tersedia');
  const rows=[];
  const pageSize=1000;
  for(let from=0;;from+=pageSize){
    const {data,error}=await supabaseClient
      .from('pokok')
      .select('*')
      .order('fid',{ascending:true})
      .range(from,from+pageSize-1);
    if(error) throw error;
    if(!data||!data.length) break;
    rows.push(...data);
    if(data.length<pageSize) break;
  }
  if(rows.length<1) throw new Error('Tiada rekod diterima daripada table pokok');
  return rows.map(makeFeatureFromSupabaseV77);
}

function setSupabaseStatusV77(text,ok=false){
  let el=document.getElementById('supabaseStatusV77');
  if(!el){
    el=document.createElement('div');
    el.id='supabaseStatusV77';
    el.style.cssText='position:fixed;right:18px;bottom:18px;z-index:10000;background:rgba(15,23,42,.94);color:#fff;padding:9px 13px;border-radius:10px;font:600 12px/1.2 Arial,sans-serif;box-shadow:0 8px 24px rgba(0,0,0,.25);';
    document.body.appendChild(el);
  }
  el.textContent=text;
  el.style.border='1px solid '+(ok?'#2bb673':'#d97706');
}

async function initSupabaseDataV77(){
  try{
    setSupabaseStatusV77('Menyambung ke database Supabase…');
    const remote=await loadSupabasePokokV77();
    all=remote;
    SUPABASE_CONNECTED_V77=true;
    populateAdvancedFilters();
    populateInventory();
    render();
    setSupabaseStatusV77('Database Supabase: '+all.length.toLocaleString('en-MY')+' rekod ✓',true);
  }catch(err){
    console.error('Supabase V77:',err);
    SUPABASE_CONNECTED_V77=false;
    setSupabaseStatusV77('Database belum bersambung — data V76 digunakan sementara');
  }
}
