// V51: one persistent set of updated point IDs. The blinking is a visual
// state on the existing single point layer; it is not a second layer.
const UPDATED_UIDS_V51=new Set();
function loadUpdatedUIDsV51(){
  try{
    const m48=JSON.parse(localStorage.getItem('pmm_ups_meta_v48')||'{}');
    Object.keys(m48).forEach(uid=>UPDATED_UIDS_V51.add(String(uid)));
  }catch(e){}
  try{
    const m50=JSON.parse(localStorage.getItem('pmm_ups_meta_v50')||'{}');
    Object.keys(m50).forEach(uid=>UPDATED_UIDS_V51.add(String(uid)));
  }catch(e){}
}
function resetUPSStateV58(){
  try{
    if(localStorage.getItem('pmm_ups_reset_v58_done')!=='1'){
      ['pmm_ups_updates_v47','pmm_ups_meta_v48','pmm_ups_meta_v50','pmm_ups_meta_v55','pmm_ups_last_sync_v53','pmm_ups_last_sync_v57'].forEach(k=>localStorage.removeItem(k));
      localStorage.setItem('pmm_ups_reset_v58_done','1');
    }
  }catch(e){}
}
