// UPS client-side updates: merge any saved changes into the embedded dataset on every load.
const UPS_STORAGE_KEY_V47='pmm_ups_updates_v47';
function loadUPSUpdatesV47(){
  try{
    const saved=JSON.parse(localStorage.getItem(UPS_STORAGE_KEY_V47)||'{}');
    all.forEach(f=>{
      const uid=String(f.properties.UID??'');
      if(saved[uid]) Object.assign(f.properties,saved[uid]);
    });
  }catch(e){ console.warn('UPS updates tidak dapat dimuat',e); }
}

const UPS_META_KEY_V48='pmm_ups_meta_v48';
function getUPSMetaV48(uid){
  try{
    const saved=JSON.parse(localStorage.getItem(UPS_META_KEY_V48)||'{}');
    return saved[String(uid)]||null;
  }catch(e){return null;}
}
function setUPSMetaV48(uid, meta){
  const saved=JSON.parse(localStorage.getItem(UPS_META_KEY_V48)||'{}');
  saved[String(uid)]=meta;
  localStorage.setItem(UPS_META_KEY_V48,JSON.stringify(saved));
}
function formatUpdatedAtV48(iso){
  if(!iso)return '';
  const d=new Date(iso);
  if(Number.isNaN(d.getTime()))return '';
  return d.toLocaleString('en-MY',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
}

const UPS_META_KEY_V50='pmm_ups_meta_v50';
function getUPSMetaV50(uid){
  try{
    const saved=JSON.parse(localStorage.getItem(UPS_META_KEY_V50)||'{}');
    return saved[String(uid)]||null;
  }catch(e){return null;}
}
function setUPSMetaV50(uid, meta){
  const saved=JSON.parse(localStorage.getItem(UPS_META_KEY_V50)||'{}');
  saved[String(uid)]=meta;
  localStorage.setItem(UPS_META_KEY_V50,JSON.stringify(saved));
}
function formatUpdatedAtV50(iso){
  if(!iso)return '';
  const d=new Date(iso);
  if(Number.isNaN(d.getTime()))return '';
  const pad=n=>String(n).padStart(2,'0');
  return `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}
function saveUPSUpdateV47(f, changes){
  const uid=String(f.properties.UID);
  const saved=JSON.parse(localStorage.getItem(UPS_STORAGE_KEY_V47)||'{}');
  saved[uid]=changes;
  localStorage.setItem(UPS_STORAGE_KEY_V47,JSON.stringify(saved));
  const nowV50=new Date().toISOString();
  if(typeof setUPSMetaV48==='function') setUPSMetaV48(uid,{updatedAt:nowV50,updatedFields:Object.keys(changes)});
  setUPSMetaV50(uid,{updatedAt:nowV50,updatedFields:Object.keys(changes)});
}
loadUPSUpdatesV47();


