let petakLayerV83=null;
let petakDataV84=[];
const petakLayerByPlotV84=new Map();
function selectedPetakFilterV84(){
  const main=document.getElementById('plot')?.value||'';
  const adv=document.getElementById('advPlot')?.value||'';
  return main||adv||'';
}
function refreshPetakDisplayV84(){
  if(!petakLayerV83||typeof map==='undefined')return;
  const enabled=!!document.getElementById('petakToggleV83')?.checked;
  const selected=selectedPetakFilterV84();
  petakLayerByPlotV84.forEach((layer,petak)=>{
    const show=enabled && (!selected || petak===selected);
    if(show){
      if(!map.hasLayer(layer)) layer.addTo(map);
      layer.bringToFront();
    }else if(map.hasLayer(layer)){
      map.removeLayer(layer);
    }
  });
}
function zoomToSelectedPetakV84(petak){
  const layer=petakLayerByPlotV84.get(String(petak));
  if(!layer||!layer.getBounds)return;
  try{ map.fitBounds(layer.getBounds().pad(.08),{padding:[40,40],maxZoom:18}); }catch(e){}
}
function loadPetakLayerV83(){
  try{
    const geo=PETAK_PMM_FINAL_DATA;
    petakDataV84=Array.isArray(geo?.features)?geo.features:[];
    petakLayerV83=L.geoJSON(geo,{
      pane:'petakPaneV83',
      style:()=>({color:'#ff6b00',weight:3,opacity:1,fill:false,fillOpacity:0,interactive:true,className:'petak-boundary-v83'}),
      onEachFeature:(feature,layer)=>{
        const p=feature.properties||{};
        const petak=String(p.PETAK??'-');
        const area=Number(p.Luas_Ha);
        const areaM2=Number(p.Luas_m2);
        const n=Number(p.NUMPOINTS);
        const dens=Number(p.Kepadatan);
        petakLayerByPlotV84.set(petak,layer);
        layer.bindTooltip('PETAK '+esc(petak),{sticky:true,direction:'top'});
        layer.bindPopup(
          `<div style="min-width:205px"><b style="font-size:15px">PETAK ${esc(petak)}</b><hr style="border:0;border-top:1px solid #e5e7eb;margin:7px 0">`+
          `<div>Luas: <b>${Number.isFinite(area)?area.toFixed(2):'-'} ha</b></div>`+
          `<div>Luas: <b>${Number.isFinite(areaM2)?areaM2.toLocaleString('en-MY',{maximumFractionDigits:2}):'-'} m²</b></div>`+
          `<div>Jumlah pokok: <b>${Number.isFinite(n)?n.toLocaleString('en-MY'):'-'}</b></div>`+
          `<div>Kepadatan: <b>${Number.isFinite(dens)?dens.toFixed(3):'-'} pokok/ha</b></div></div>`
        );
        layer.on('click',()=>{
          const plotEl=document.getElementById('plot');
          if(plotEl) plotEl.value=petak;
          const advEl=document.getElementById('advPlot');
          if(advEl) advEl.value='';
          const sf=document.getElementById('searchField'); if(sf) sf.value='PETAK';
          const si=document.getElementById('searchInput'); if(si) si.value=petak;
          setSelectedPetakV88(petak);
          if(typeof render==='function') render();
          setTimeout(()=>zoomToSelectedPetakV84(petak),50);
        });
      }
    });
    refreshPetakDisplayV84();
  }catch(err){ console.error('Petak V83:',err); }
}
map.createPane('petakPaneV83');
map.getPane('petakPaneV83').style.zIndex=700;
loadPetakLayerV83();



function filtered(){
  const q=document.getElementById('searchInput').value.trim().toLowerCase();
  const field=document.getElementById('searchField').value;
  const pl=document.getElementById('plot').value;
  const st=document.getElementById('status').value;
  const apl=document.getElementById('advPlot')?.value||"";
  const ast=document.getElementById('advStatus')?.value||"";
  const ame=document.getElementById('advMethod')?.value||"";
  const asp=document.getElementById('advSpecies')?.value||"";
  const minD=parseFloat(document.getElementById('advMinDia')?.value);
  const maxD=parseFloat(document.getElementById('advMaxDia')?.value);
  const minH=parseFloat(document.getElementById('advMinHeight')?.value);
  const maxH=parseFloat(document.getElementById('advMaxHeight')?.value);
  return all.filter(f=>{
    const p=f.properties;
    let match=true;
    if(q){
      const value=field ? String(p[field]??"") :
        [p.UID,p["ID POKOK"],p["NAMA POKOK"],p.PETAK,p["STATUS POKOK"],p["KAEDAH_TINGGI"]].join(" ");
      // ID Pokok is an identifier: when that field is selected, require an exact match.
      match=field==="ID POKOK" ? value.trim().toLowerCase()===q : value.toLowerCase().includes(q);
    }
    const dia=Number(p["DIAMETER (cm)"]), h=Number(p["TINGGI_FINAL (m)"]);
    return match &&
      (!pl||String(p.PETAK)===pl) &&
      (!st||String(p["STATUS POKOK"])===st) &&
      (!apl||String(p.PETAK)===apl) &&
      (!ast||String(p["STATUS POKOK"])===ast) &&
      (!ame||String(p["KAEDAH_TINGGI"])===ame) &&
      (!asp||String(p["NAMA POKOK"])===asp) &&
      (!Number.isFinite(minD)||(!Number.isFinite(dia)?false:dia>=minD)) &&
      (!Number.isFinite(maxD)||(!Number.isFinite(dia)?false:dia<=maxD)) &&
      (!Number.isFinite(minH)||(!Number.isFinite(h)?false:h>=minH)) &&
      (!Number.isFinite(maxH)||(!Number.isFinite(h)?false:h<=maxH));
  });
}

let selectedTreeUIDV66=null;

function treeStyleV66(f, selected=false){
  const p=f.properties||{};
  const st=String(p["STATUS POKOK"]??"").trim().toUpperCase();
  const fill=st==="MATI"?"#ef3333":st==="HIDUP"?"#1bc65a":"#f2c51c";
  if(selected){
    return {
      radius:8.5, weight:2.8, color:"#ffe066", opacity:1,
      fillColor:"#ffb000", fillOpacity:1, pane:"treePointsPane",
      className:"selected-tree-marker-v66"
    };
  }
  return {
    radius:5.8, weight:1.7, color:"#ffffff", opacity:1,
    fillColor:fill, fillOpacity:.98, pane:"treePointsPane",
    className:UPDATED_UIDS_V51.has(String(p.UID))?"updated-tree-marker-v53 blink-on":""
  };
}
function applySelectedTreeV66(uid){
  selectedTreeUIDV66=uid?String(uid):null;
  markerMap.forEach((m,key)=>{
    const f=all.find(x=>String(x.properties.UID)===String(key));
    if(f) m.setStyle(treeStyleV66(f,String(key)===selectedTreeUIDV66));
  });
}

function render(){
  const rows=filtered();
  markers.clearLayers(); markerMap.clear();
  rows.forEach(f=>{
    const p=f.properties,[lat,lng]=xy(f);
    const st=String(p["STATUS POKOK"]??"").trim().toUpperCase();
    const fill=st==="MATI"?"#ef3333":st==="HIDUP"?"#1bc65a":"#f2c51c";
    const stroke=st==="MATI"?"#8b1e1e":st==="HIDUP"?"#0a6a3f":"#8a6d00";
    const isUpdated=UPDATED_UIDS_V51.has(String(p.UID));
    const isSelected=selectedTreeUIDV66!==null && String(p.UID)===selectedTreeUIDV66;
    const m=L.circleMarker([lat,lng],treeStyleV66(f,isSelected));
    m.bindTooltip(`${esc(p.UID)} — ${esc(p["NAMA POKOK"])}`,{direction:"top",offset:[0,-7],sticky:true});
    m.bindPopup(`<b>${esc(p.UID)}</b><br>${esc(p["NAMA POKOK"])}<br><span style="color:${stroke};font-weight:700">${esc(st)}</span>${isUpdated?'<br><span style="color:#b77900;font-weight:800">✓ Telah dikemas kini</span>':''}`);

    m.on("click",()=>{
      applySelectedTreeV66(p.UID);
      showInfo(f);
    });
    m.addTo(markers); markerMap.set(p.UID,m);
  });
  document.getElementById('visibleCount').textContent=rows.length.toLocaleString('en-MY')+" pokok dipaparkan"; updateSearchStatusV33();
  refreshPetakDisplayV84();
  // Updated points are pulsed directly via markerMap in V55.
  const q=document.getElementById('searchInput').value.trim();
  if(q && rows.length){
    const pts=rows.map(f=>xy(f));
    if(pts.length===1) map.setView(pts[0],19);
    else map.fitBounds(L.latLngBounds(pts),{padding:[70,70],maxZoom:19});
  }
}
