function setTreePhoto(p){
  const box=document.getElementById('treePhoto');
  if(!box) return;
  const id=String(p["ID POKOK"]??"").trim();
  box.innerHTML='';
  if(!id){ box.innerHTML='<div class="photo-placeholder">Gambar belum tersedia</div>'; return; }
  const img=document.createElement('img');
  img.alt='Gambar pokok ID '+esc(id);
  img.decoding='async';
  img.loading='eager';
  img.style.width='100%';
  img.style.height='130px';
  img.style.objectFit='cover';
  img.onerror=function(){
    const localA='images/'+id+'.jpg';
    const localB='images/'+id+'.JPG';
    const embedded=(typeof EMBEDDED_IMAGES!=='undefined' && EMBEDDED_IMAGES[id])||'';
    if(img.src.indexOf(localA)===-1 && img.src.indexOf(localB)===-1){
      img.src=localA;
    }else if(embedded && img.src!==new URL(embedded,document.baseURI).href && img.src!==embedded){
      img.src=embedded;
    }else{
      box.innerHTML='<div class="photo-placeholder">Gambar untuk ID '+esc(id)+' belum tersedia</div>';
    }
  };
  box.appendChild(img);
  if(TREE_IMAGE_DATA_V88[id]) img.src=TREE_IMAGE_DATA_V88[id];
  else img.src='images/'+id+'.jpg';
}



function updateLastUpdatedInfoV50(uid){
  const box=document.getElementById('lastUpdatedInfoV50');
  const text=document.getElementById('lastUpdatedTextV50');
  if(!box||!text)return;
  let meta=null;
  if(typeof getUPSMetaV50==='function') meta=getUPSMetaV50(uid);
  if(!meta && typeof getUPSMetaV48==='function') meta=getUPSMetaV48(uid);
  if(meta && meta.updatedAt){
    text.textContent=formatUpdatedAtV50(meta.updatedAt);
    box.classList.remove('never');
  }else{
    text.textContent='Belum pernah dikemas kini';
    box.classList.add('never');
  }
}
function showInfo(f){
  currentFeature=f; const p=f.properties,[lat,lng]=xy(f); updateLastUpdatedInfoV50(p.UID);
  setTreePhoto(p);
  const pf=getPetakFeatureByNameV86(p.PETAK);
  const petakBox=document.getElementById('petakMetricsInTree');
  if(petakBox){
    const q=pf?.properties||{};
    petakBox.innerHTML=[
      ['Petak',p.PETAK??'-'],
      ['Luas Petak (ha)',Number.isFinite(Number(q.Luas_Ha))?Number(q.Luas_Ha).toFixed(2):'-'],
      ['Luas Petak (m²)',Number.isFinite(Number(q.Luas_m2))?Number(q.Luas_m2).toLocaleString('en-MY',{maximumFractionDigits:2}):'-'],
      ['Jumlah Pokok Petak',Number.isFinite(Number(q.NUMPOINTS))?Number(q.NUMPOINTS).toLocaleString('en-MY'):'-'],
      ['Kepadatan Petak',Number.isFinite(Number(q.Kepadatan))?Number(q.Kepadatan).toFixed(3)+' pokok/ha':'-']
    ].map(([a,b])=>`<div class="metric"><div class="m-label">${esc(a)}</div><div class="m-val">${esc(b)}</div></div>`).join('');
  }
  document.getElementById('d_id').textContent=p["ID POKOK"]??"-"; document.getElementById('d_species').textContent=p["NAMA POKOK"]??"-"; document.getElementById('d_plot').textContent=p.PETAK??"-";
  const s=p["STATUS POKOK"]??"-"; document.getElementById('d_status').innerHTML=`<span class="status ${s==="HIDUP"?"live":s==="MATI"?"dead":"other"}">${esc(s)}</span>`;
  const metricFields=[
    ["Diameter (cm)",p["DIAMETER (cm)"]],["Ketinggian (m)",p["TINGGI_FINAL (m)"]],
    ["Lilitan (cm)",p["LILITAN (cm)"]],["Kaedah Tinggi",p["KAEDAH_TINGGI"]],
    ["Biomassa (kg)",p["BERAT KERING (kg)"]],["Karbon (kg)",p["lb - kg"]],
    ["CO₂ Terkumpul (kg)",p["CO₂ TERKUMPUL (kg CO₂)"]],["Anggaran Serapan CO₂ (kg/tahun)",p["PURATA ANGGARAN SERAP CO₂ (kg/tahun)"]]
  ];
  document.getElementById('metrics').innerHTML=metricFields.map(([a,b])=>`<div class="metric"><div class="m-label">${esc(a)}</div><div class="m-val">${num(b)}</div></div>`).join("");
  const ups=[["Umur Pokok",p["UMUR POKOK"]],["Tarikh Terima",p["TARIKH TERIMA"]],["Harga Perolehan Asal",p["HARGA PEROLEHAN ASAL"]],["Anggaran Nilai Semasa",p["ANGGARAN NILAI SEMASA"]],["X Coordinate",p["X_COORD"]],["Y Coordinate",p["Y_COORD"]]];
  document.getElementById('upsMetrics').innerHTML=ups.map(([a,b])=>`<div class="metric"><div class="m-label">${esc(a)}</div><div class="m-val">${esc(b??"-")}</div></div>`).join("");
  document.getElementById('infoPanel').classList.add("show"); map.setView([lat,lng],18);
}
function closeInfo(){
  selectedTreeUIDV66=null;
document.getElementById('infoPanel').classList.remove("show");currentFeature=null}
function updateCurrentTreeFromInfo(){
  const f=currentFeature;
  if(!f)return;
  const proceed=()=>{
    upsCurrentFeatureV47=f;
    currentFeature=f;
    closeInfo();
    showUPS();
    requestAnimationFrame(()=>selectUPSTreeForEditV63(f));
  };
  if(window.requireUPSAccessV79) window.requireUPSAccessV79(proceed); else proceed();
}

let selectedPetakV88='';
function setSelectedPetakV88(petak, opts={}){
  selectedPetakV88=String(petak||'').trim().toUpperCase();
  if(!selectedPetakV88){
    clearPetakSearchCardV86();
  }
  const anPlotEl=document.getElementById('anPlot');
  if(anPlotEl && selectedPetakV88 && [...anPlotEl.options].some(o=>o.value===selectedPetakV88)){
    anPlotEl.value=selectedPetakV88;
  }
  const pf=selectedPetakV88?getPetakFeatureByNameV86(selectedPetakV88):null;
  if(pf) showPetakSearchCardV86(pf);
  updatePetakAnalysisV88();
  updateAnalysis();
}
function getSelectedPetakFeatureV88(){
  const key=selectedPetakV88;
  return key ? petakDataV84.find(f=>String(f.properties?.PETAK??'').toUpperCase()===key) : null;
}
function updatePetakAnalysisV88(){
  const box=document.getElementById('petakSelectedSummaryV88');
  const pf=getSelectedPetakFeatureV88();
  if(!box) return;
  if(!pf){box.style.display='none';box.innerHTML='';return;}
  const p=pf.properties||{};
  box.style.display='block';
  box.innerHTML=`<b>Analisis Petak ${esc(p.PETAK??'-')}</b> &nbsp;•&nbsp; Luas: <b>${Number(p.Luas_Ha).toFixed(2)} ha</b> (${Number(p.Luas_m2).toLocaleString('en-MY',{maximumFractionDigits:2})} m²) &nbsp;•&nbsp; Jumlah pokok: <b>${Number(p.NUMPOINTS||0).toLocaleString('en-MY')}</b> &nbsp;•&nbsp; Kepadatan: <b>${Number(p.Kepadatan).toFixed(3)} pokok/ha</b>`;
}

