document.getElementById('plot').onchange=()=>{ const v=document.getElementById('plot').value; if(v){ setSelectedPetakV88(v); } else { selectedPetakV88=''; clearPetakSearchCardV86(); updatePetakAnalysisV88(); updateAnalysis(); } render(); if(v) setTimeout(()=>zoomToSelectedPetakV84(v),50); }; document.getElementById('status').onchange=render;
function normalizePetakSearchV86(q){
  return String(q||'').trim().replace(/^petak\s*/i,'').toUpperCase();
}
function getPetakFeatureByNameV86(name){
  const key=normalizePetakSearchV86(name);
  return petakDataV84.find(f=>String(f.properties?.PETAK??'').toUpperCase()===key)||null;
}
function clearPetakSearchCardV86(){
  const card=document.getElementById('petakSearchCardV86');
  if(card){card.classList.remove('show');card.innerHTML='';}
}
function showPetakSearchCardV86(feature){
  const card=document.getElementById('petakSearchCardV86');
  if(!card||!feature)return;
  const p=feature.properties||{};
  const area=Number(p.Luas_Ha), areaM2=Number(p.Luas_m2), n=Number(p.NUMPOINTS), dens=Number(p.Kepadatan);
  card.innerHTML=`
    <div class="ps-head">
      <div><div class="ps-title">PETAK ${esc(p.PETAK??'-')}</div><div class="ps-sub">Maklumat kawasan hasil carian</div></div>
      <button class="ps-close" type="button" aria-label="Tutup">×</button>
    </div>
    <div class="ps-grid">
      <div class="ps-metric"><div class="k">Luas (ha)</div><div class="v">${Number.isFinite(area)?area.toFixed(2):'-'} ha</div></div>
      <div class="ps-metric"><div class="k">Luas (m²)</div><div class="v">${Number.isFinite(areaM2)?areaM2.toLocaleString('en-MY',{maximumFractionDigits:2}):'-'}</div></div>
      <div class="ps-metric"><div class="k">Jumlah pokok</div><div class="v">${Number.isFinite(n)?n.toLocaleString('en-MY'):'-'}</div></div>
      <div class="ps-metric"><div class="k">Kepadatan</div><div class="v">${Number.isFinite(dens)?dens.toFixed(3):'-'}</div></div>
    </div>
    <div class="ps-note">Carian telah disegerakkan: hanya sempadan dan titik pokok bagi Petak ${esc(p.PETAK??'-')} dipaparkan.</div>`;
  card.classList.add('show');
  card.querySelector('.ps-close')?.addEventListener('click',clearPetakSearchCardV86);
}
function syncPetakSearchV86(){
  const field=document.getElementById('searchField').value;
  if(field!=='PETAK') return false;
  const q=document.getElementById('searchInput').value.trim();
  if(!q){ clearPetakSearchCardV86(); return false; }
  const feature=getPetakFeatureByNameV86(q);
  if(!feature){ clearPetakSearchCardV86(); return false; }
  const p=feature.properties||{};
  const petak=String(p.PETAK??'');
  const plotEl=document.getElementById('plot'); if(plotEl) plotEl.value=petak;
  const advEl=document.getElementById('advPlot'); if(advEl) advEl.value='';
  setSelectedPetakV88(petak);
  render();
  setTimeout(()=>zoomToSelectedPetakV84(petak),80);
  return true;
}
function doSearchList(){
  const q=document.getElementById('searchInput').value.trim().toLowerCase(), box=results, field=document.getElementById('searchField').value;
  if(!q){box.style.display='none';box.innerHTML='';return}
  if(field==='PETAK'){
    const qn=normalizePetakSearchV86(q);
    const rows=petakDataV84.filter(f=>String(f.properties?.PETAK??'').toUpperCase().includes(qn));
    box.innerHTML=rows.map(f=>{const p=f.properties||{};return `<div class="result petak-result-v86" data-petak="${esc(p.PETAK)}"><b>▱ PETAK ${esc(p.PETAK)}</b><span>Luas: ${Number(p.Luas_Ha).toFixed(2)} ha • ${Number(p.Luas_m2).toLocaleString('en-MY',{maximumFractionDigits:2})} m² • ${Number(p.NUMPOINTS).toLocaleString('en-MY')} pokok • ${Number(p.Kepadatan).toFixed(3)} pokok/ha</span></div>`}).join('')||'<div class="result">Petak tidak ditemui.</div>';
    box.style.display='block';
    box.querySelectorAll('.petak-result-v86').forEach(el=>el.onclick=()=>{
      document.getElementById('searchInput').value=el.dataset.petak;
      box.style.display='none';
      syncPetakSearchV86();
    });
    return;
  }
  const rows=all.filter(f=>[f.properties.UID,f.properties["ID POKOK"],f.properties["NAMA POKOK"],f.properties.PETAK].join(" ").toLowerCase().includes(q)).slice(0,30);
  box.innerHTML=rows.map(f=>{const p=f.properties;return `<div class="result" data-uid="${esc(p.UID)}"><b>${esc(p.UID)} — ${esc(p["NAMA POKOK"])}</b><span>Petak ${esc(p.PETAK)} • ${esc(p["STATUS POKOK"])}</span></div>`}).join('')||'<div class="result">Tiada rekod ditemui.</div>';
  box.style.display='block';
  box.querySelectorAll('.result[data-uid]').forEach(el=>el.onclick=()=>{const f=all.find(x=>x.properties.UID===el.dataset.uid);if(f){document.getElementById('searchInput').value=f.properties.UID;box.style.display='none';setSelectedPetakV88(f.properties.PETAK||'');showInfo(f)}});
}

