function switchBaseV42(layer,name){
  if(activeBaseV42 && map.hasLayer(activeBaseV42)) map.removeLayer(activeBaseV42);
  layer.addTo(map); activeBaseV42=layer;
  document.querySelectorAll('.bm-option-v42').forEach(b=>b.classList.toggle('active',b.dataset.bm===name));
}
function setUavV42(on){
  if(on){
    uavOverlayV42.addTo(map);
    uavOverlayV42.setOpacity(Number(document.getElementById('uavOpacityV42').value)/100);
    const b=uavOverlayV42.getBounds();
    if(!b.contains(map.getCenter())) map.fitBounds(b.pad(0.08));
  }else if(map.hasLayer(uavOverlayV42)){
    map.removeLayer(uavOverlayV42);
  }
}

document.getElementById('treeToggleV44').onchange=e=>{
  if(e.target.checked){
    if(!map.hasLayer(markers)) markers.addTo(map);
    if(typeof render==='function') render();
  }else if(map.hasLayer(markers)){
    map.removeLayer(markers);
  }
};

