function positionBasemapMenuV57(){
  const btn=document.getElementById('layers'),menu=document.getElementById('basemapMenuV42');
  if(!btn||!menu)return;
  const r=btn.getBoundingClientRect();
  menu.style.display='block';
  const mw=menu.offsetWidth||260, mh=menu.offsetHeight||360;
  let left=r.right+10, top=r.top;
  if(left+mw>window.innerWidth-10) left=r.left-mw-10;
  if(left<10) left=10;
  if(top+mh>window.innerHeight-10) top=window.innerHeight-mh-10;
  if(top<70) top=70;
  menu.style.left=Math.round(left)+'px';
  menu.style.top=Math.round(top)+'px';
}
document.getElementById('layers').onclick=(e)=>{
  e.preventDefault();e.stopPropagation();
  const menu=document.getElementById('basemapMenuV42');
  if(getComputedStyle(menu).display==='none'){
    positionBasemapMenuV57();
  }else{
    menu.style.display='none';
  }
};

document.querySelectorAll('.bm-option-v42').forEach(b=>b.onclick=()=>{
  if(b.dataset.bm==='esri') switchBaseV42(baseEsri,'esri');
  if(b.dataset.bm==='osm') switchBaseV42(baseOSM,'osm');
  if(b.dataset.bm==='esriStreet') switchBaseV42(baseEsriStreet,'esriStreet');
});
document.getElementById('uavToggleV42').onchange=e=>setUavV42(e.target.checked);
document.getElementById('uavOpacityV42').oninput=e=>{
  const v=Number(e.target.value);
  document.getElementById('uavOpacityValueV42').textContent=v+'%';
  uavOverlayV42.setOpacity(v/100);
};

