let upsCurrentFeatureV47=null;
function valV47(id){return document.getElementById(id).value;}
function setValV47(id,val){document.getElementById(id).value=(val==null?'':val);}
function numTxtV47(v){return v==null||v===''?'-':Number(v).toLocaleString('en-MY',{maximumFractionDigits:2});}

let upsSearchRowsV59=[];
function upsSearchV47(){
  const type=document.getElementById('upsSearchTypeV47').value;
  const q=document.getElementById('upsSearchInputV47').value.trim().toLowerCase();
  const box=document.getElementById('upsSearchResultsV47');
  const editor=document.getElementById('upsEditorV47');
  const empty=document.getElementById('upsNoSelectionV47');
  editor.style.display='none'; empty.style.display='block'; upsCurrentFeatureV47=null;

  if(!q){
    box.innerHTML='';
    upsSearchRowsV59=all.slice();
    renderUPSMiniMapV59(upsSearchRowsV59,true);
    return;
  }

  // The exact same set of records shown in the search results is the set
  // shown on the UPS map.
  const rows=all.filter(f=>{
    const value=String(f.properties[type]??'').trim().toLowerCase();
    return type==='ID POKOK' ? value===q : value.includes(q);
  });
  upsSearchRowsV59=rows;
  box.innerHTML=rows.slice(0,20).length?rows.slice(0,20).map(f=>{
    const p=f.properties;
    const meta=getUPSMetaV48(p.UID);
    const updated=meta?`<span class="ups-result-v48-updated">✓ Dikemas kini ${formatUpdatedAtV48(meta.updatedAt)}</span>`:'';
    return `<button type="button" class="ups-result-v47" data-idx="${all.indexOf(f)}"><div class="ups-result-main-v47"><b>${esc(p.UID)} — ${esc(p["NAMA POKOK"])}</b><span>📍 Petak ${esc(p.PETAK)} • ID Pokok ${esc(p["ID POKOK"])} • ${esc(p["STATUS POKOK"]||"Lain")} ${updated}</span></div><span class="ups-result-action-v47">Pilih</span></button>`;
  }).join(''):`<div class="ups-empty-v47" style="margin-top:0"><div>⚠️</div><b>Rekod tidak dijumpai</b><span>Cuba UID, ID Pokok atau Petak yang lain.</span></div>`;
  box.querySelectorAll('.ups-result-v47').forEach(b=>b.onclick=()=>selectUPSTreeForEditV63(all[Number(b.dataset.idx)],true));
  ensureUPSMiniMapV48();
  renderUPSMiniMapV59(upsSearchRowsV59,true);
}


let upsMiniMapV48=null, upsMiniMarkersV48=null, upsMiniSelectedV48=null;
function ensureUPSMiniMapV48(){
  if(upsMiniMapV48)return;
  upsMiniMapV48=L.map('upsMiniMapV48',{zoomControl:true,attributionControl:true}).setView([2.1684,102.4307],16);
  upsMiniMapV48.createPane('treePointsPaneV58'); upsMiniMapV48.getPane('treePointsPaneV58').style.zIndex=650;
  L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{
    maxZoom:21,attribution:'Tiles © Esri'
  }).addTo(upsMiniMapV48);
  if(typeof uavOverlayV42!=='undefined' && uavOverlayV42._url && uavOverlayV42.getBounds){
    L.imageOverlay(uavOverlayV42._url,uavOverlayV42.getBounds(),{
      opacity:1,interactive:false,zIndex:250,attribution:'Imej UAV PMM'
    }).addTo(upsMiniMapV48);
  }
  upsMiniMarkersV48=L.layerGroup().addTo(upsMiniMapV48);
  renderUPSMiniMapV59(all,false);
}
function upsPointColorV59(p){
  const st=String(p["STATUS POKOK"]??"").trim().toUpperCase();
  return st==="MATI"?"#ef3333":st==="HIDUP"?"#1bc65a":"#f2c51c";
}
function upsTreePopupV59(f){
  const p=f.properties, st=String(p["STATUS POKOK"]??"Lain / Tidak Dikenal Pasti");
  const stColor=st.toUpperCase()==="MATI"?'#d22':st.toUpperCase()==="HIDUP"?'#058b62':'#b18400';
  const idx=all.indexOf(f);
  return `<div class="ups-tree-popup-v59">
    <h4>Maklumat Pokok</h4>
    <div class="row"><span class="label">UID</span><span class="val">${esc(p.UID??'-')}</span></div>
    <div class="row"><span class="label">ID Pokok</span><span class="val">${esc(p["ID POKOK"]??'-')}</span></div>
    <div class="row"><span class="label">Nama Pokok</span><span class="val">${esc(p["NAMA POKOK"]??'-')}</span></div>
    <div class="row"><span class="label">Petak</span><span class="val">${esc(p.PETAK??'-')}</span></div>
    <div class="row"><span class="label">Status</span><span class="val status" style="color:${stColor}">${esc(st||'Lain')}</span></div>
    <button class="pick" type="button" onclick="selectUPSTreeForEditV63(all[${idx}],true);">Kemas Kini Data Pokok</button>
  </div>`;
}
function renderUPSMiniMapV59(features,fit){
  if(!upsMiniMapV48||!upsMiniMarkersV48)return;
  upsMiniMarkersV48.clearLayers();
  if(upsMiniSelectedV48){upsMiniMapV48.removeLayer(upsMiniSelectedV48);upsMiniSelectedV48=null;}
  const bounds=[];
  features.forEach(f=>{
    const p=f.properties, c=xy(f); bounds.push(c);
    const m=L.circleMarker(c,{radius:5.8,weight:1.7,color:'#ffffff',fillColor:upsPointColorV59(p),fillOpacity:.98,pane:'treePointsPaneV58'});
    m.__treeUIDV59=String(p.UID);
    m.bindTooltip(`${esc(p.UID)} — ${esc(p["NAMA POKOK"]||'')}`,{sticky:true});
    m.bindPopup(upsTreePopupV59(f),{maxWidth:280,autoPan:true,closeButton:true});
    m.on('click',()=>{
  upsCurrentFeatureV47=f;
  currentFeature=f;
  m.openPopup();
  focusUPSMiniMapV48(f);
  selectUPSTreeForEditV63(f,true);
});
    m.addTo(upsMiniMarkersV48);
  });
  if(fit){
    if(bounds.length>1) upsMiniMapV48.fitBounds(L.latLngBounds(bounds).pad(.05));
    else if(bounds.length===1) upsMiniMapV48.setView(bounds[0],19,{animate:true});
  }
  setTimeout(()=>upsMiniMapV48.invalidateSize(),80);
}
function focusUPSMiniMapV48(f){
  ensureUPSMiniMapV48();
  if(upsMiniSelectedV48){upsMiniMapV48.removeLayer(upsMiniSelectedV48);}
  const c=xy(f);
  upsMiniSelectedV48=L.circleMarker(c,{radius:12,weight:3,color:"#0b6f58",fillColor:"#ffffff",fillOpacity:0,interactive:false}).addTo(upsMiniMapV48);
  upsMiniSelectedV48.bringToFront();
  const p=f.properties;
  upsMiniSelectedV48.bindTooltip(`<b>${esc(p.UID)}</b> • ID Pokok ${esc(p["ID POKOK"])}`,{permanent:true,direction:"top",offset:[0,-10]});
  upsMiniMapV48.setView(c,19,{animate:true});
  setTimeout(()=>upsMiniMapV48.invalidateSize(),80);
}
function openSelectedOnMainMapV48(){
  if(!upsCurrentFeatureV47)return;
  document.getElementById('upsScreenV46').style.display='none';
  showMap();
  const c=xy(upsCurrentFeatureV47);
  map.setView(c,19);
  if(typeof showInfo==='function')showInfo(upsCurrentFeatureV47);
}
function selectUPSTreeForEditV63(f,focusEditor=false){
  if(!f || !f.properties)return;
  upsCurrentFeatureV47=f;
  currentFeature=f;

  // Fill the editor immediately from the exact clicked record.
  openUPSEditorV47(f);

  // Keep the selected point highlighted on the UPS map.
  try{ focusUPSMiniMapV48(f); }catch(e){}

  const editor=document.getElementById('upsEditorV47');
  if(editor){
    editor.style.display='block';
    const empty=document.getElementById('upsNoSelectionV47');
    if(empty)empty.style.display='none';

    // Re-apply values once after the DOM paints, preventing any stale/default
    // form state from overwriting the selected record.
    requestAnimationFrame(()=>{
      const p=f.properties;
      setValV47('u_UID',p.UID);
      setValV47('u_PETAK',p.PETAK);
      setValV47('u_ID',p["ID POKOK"]);
      setValV47('u_NAME',p["NAMA POKOK"]);
      setValV47('u_STATUS',p["STATUS POKOK"]);
      setValV47('u_AGE',p["UMUR POKOK"]);
      setValV47('u_CIRC',p["LILITAN (cm)"]);
      setValV47('u_DIA',p["DIAMETER (cm)"]);
      setValV47('u_H',p["TINGGI_FINAL (m)"]);
      setValV47('u_METHOD',p["KAEDAH_TINGGI"]);
      setValV47('u_DATE',p["TARIKH TERIMA"]);
      setValV47('u_PRICE',p["HARGA PEROLEHAN ASAL"]);
      setValV47('u_VALUE',p["ANGGARAN NILAI SEMASA"]);
      document.getElementById('r_BIOMASS').textContent=numTxtV47(p["BERAT KERING (kg)"]);
      document.getElementById('r_CARBON').textContent=numTxtV47(p["lb - kg"]);
      document.getElementById('r_CO2').textContent=numTxtV47(p["CO₂ TERKUMPUL (kg CO₂)"]);
      document.getElementById('r_CO2Y').textContent=numTxtV47(p["PURATA ANGGARAN SERAP CO₂ (kg/tahun)"]);
    });

    if(focusEditor){
      setTimeout(()=>editor.scrollIntoView({behavior:'smooth',block:'start'}),120);
    }
  }
}
function openUPSEditorV47(f){
  upsCurrentFeatureV47=f;
  const p=f.properties;
  document.getElementById('upsEditorV47').style.display='block';
  document.getElementById('upsNoSelectionV47').style.display='none';
  document.getElementById('upsEditorTitleV47').textContent=p.UID||'-';
  document.getElementById('upsEditorMetaV47').textContent=`ID Pokok ${p["ID POKOK"]??"-"} • Petak ${p.PETAK??"-"} • ${p["NAMA POKOK"]??"-"}`;
  setValV47('u_UID',p.UID); setValV47('u_PETAK',p.PETAK); setValV47('u_ID',p["ID POKOK"]); setValV47('u_NAME',p["NAMA POKOK"]);
  setValV47('u_STATUS',p["STATUS POKOK"]); setValV47('u_AGE',p["UMUR POKOK"]); setValV47('u_CIRC',p["LILITAN (cm)"]); setValV47('u_DIA',p["DIAMETER (cm)"]);
  setValV47('u_H',p["TINGGI_FINAL (m)"]); setValV47('u_METHOD',p["KAEDAH_TINGGI"]); setValV47('u_DATE',p["TARIKH TERIMA"]);
  setValV47('u_PRICE',p["HARGA PEROLEHAN ASAL"]); setValV47('u_VALUE',p["ANGGARAN NILAI SEMASA"]);
  document.getElementById('r_BIOMASS').textContent=numTxtV47(p["BERAT KERING (kg)"]);
  document.getElementById('r_CARBON').textContent=numTxtV47(p["lb - kg"]);
  document.getElementById('r_CO2').textContent=numTxtV47(p["CO₂ TERKUMPUL (kg CO₂)"]);
  document.getElementById('r_CO2Y').textContent=numTxtV47(p["PURATA ANGGARAN SERAP CO₂ (kg/tahun)"]);
  const meta=getUPSMetaV48(p.UID);
  if(meta){
    document.getElementById('upsSaveStateV47').textContent='✓ Kemas kini terakhir: '+formatUpdatedAtV48(meta.updatedAt);
    document.getElementById('upsSaveStateV47').classList.add('saved');
  }else{
    document.getElementById('upsSaveStateV47').textContent='Belum pernah dikemas kini';
    document.getElementById('upsSaveStateV47').classList.remove('saved');
  }
  focusUPSMiniMapV48(f);
  if(typeof showInfo==='function' && currentFeature===f) showInfo(f);
  document.getElementById('upsUpdateSummaryV48').innerHTML=meta?`<div class="updated-row-v48"><span><b>✓ Rekod pernah dikemas kini</b> • ${formatUpdatedAtV48(meta.updatedAt)}</span><span>${meta.updatedFields?.length||0} medan</span></div>`:'';
  window.scrollTo(0,0);
}

const UPS_META_KEY_V55='pmm_ups_meta_v55';
function getUPSMetaV55(uid){
  try{
    const o=JSON.parse(localStorage.getItem(UPS_META_KEY_V55)||'{}');
    return o[String(uid)]||null;
  }catch(e){return null}
}
function setUPSMetaV55(uid,meta){
  const o=JSON.parse(localStorage.getItem(UPS_META_KEY_V55)||'{}');
  o[String(uid)]=meta;
  localStorage.setItem(UPS_META_KEY_V55,JSON.stringify(o));
}
const HISTORY_FIELD_LABEL_V55={
  "STATUS POKOK":"Status Pokok","UMUR POKOK":"Umur Pokok","LILITAN (cm)":"Lilitan (cm)",
  "DIAMETER (cm)":"Diameter (cm)","TINGGI_FINAL (m)":"Tinggi Final (m)","KAEDAH_TINGGI":"Kaedah Tinggi",
  "TARIKH TERIMA":"Tarikh Terima","HARGA PEROLEHAN ASAL":"Harga Perolehan Asal","ANGGARAN NILAI SEMASA":"Anggaran Nilai Semasa"
};
function valLabelV55(v){return v==null||v===""?"-":String(v)}
function renderUPSHistoryV57(){
  const box=document.getElementById('upsHistoryListV55'),count=document.getElementById('upsHistoryCountV55');
  if(!box||!count)return;
  const latest=(()=>{try{return JSON.parse(localStorage.getItem(UPS_META_KEY_V55)||'{}')}catch(e){return {}}})();
  const meta50=(()=>{try{return JSON.parse(localStorage.getItem(UPS_META_KEY_V50)||'{}')}catch(e){return {}}})();
  const saved47=(()=>{try{return JSON.parse(localStorage.getItem(UPS_STORAGE_KEY_V47)||'{}')}catch(e){return {}}})();
  const uids=[...new Set([...Object.keys(saved47),...Object.keys(latest),...Object.keys(meta50)])];
  const items=uids.map(uid=>{
    const f=all.find(x=>String(x.properties.UID)===String(uid));
    const p=f?.properties||{};
    const meta=latest[uid]||meta50[uid]||{};
    let changes=meta.after||meta.changes||saved47[uid]||{};
    let before=meta.before||{};
    // Legacy records without before/after: compare saved value against
    // the original embedded dataset, so unchanged fields are not shown.
    if(!meta.before && !meta.after){
      const base=BASE_PROPS_V57[uid]||{};
      const filtered={};
      Object.keys(changes).forEach(k=>{
        if(String(base[k]??'').trim()!==String(changes[k]??'').trim()) filtered[k]=changes[k];
      });
      changes=filtered;
    }
    const fields=Object.keys(changes).filter(k=>{
      const b=before[k], a=changes[k];
      return (before&&Object.prototype.hasOwnProperty.call(before,k))
        ? String(b??'').trim()!==String(a??'').trim()
        : true;
    });
    const at=meta.updatedAt||'';
    return {uid,f,p,changes,before,fields,at};
  }).filter(x=>x.fields.length||x.at).sort((a,b)=>new Date(b.at||0)-new Date(a.at||0));

  count.textContent=items.length+' rekod';
  if(!items.length){
    box.innerHTML='<div class="ups-history-empty-v55">Belum ada pokok yang dikemas kini.</div>';
    return;
  }

  box.innerHTML=items.map(x=>{
    const changeHtml=x.fields.length?x.fields.map(k=>{
      const label=HISTORY_FIELD_LABEL_V55[k]||k;
      const hasBefore=Object.prototype.hasOwnProperty.call(x.before,k);
      const after=x.changes[k];
      if(hasBefore){
        return `<div class="ups-change-v55"><span class="field">${esc(label)}</span><span class="before">${esc(valLabelV55(x.before[k]))}</span><span>→</span><span class="after">${esc(valLabelV55(after))}</span></div>`;
      }
      return `<div class="ups-change-v55"><span class="field">${esc(label)}</span><span class="after">→ ${esc(valLabelV55(after))}</span></div>`;
    }).join(''):'<div class="ups-change-v55"><span class="after">Tiada perubahan medan direkodkan.</span></div>';

    return `<div class="ups-history-item-v55">
      <div class="ups-history-item-head-v55">
        <b>Apa yang berubah</b>
        <span class="ups-history-time-v55">${x.at?formatUpdatedAtV50(x.at):''}</span>
      </div>
      <div class="ups-history-change-list-v55">${changeHtml}</div>
      <div class="ups-history-meta-v55">
        <b>UID:</b> ${esc(x.uid)} &nbsp;•&nbsp;
        <b>ID Pokok:</b> ${esc(x.p["ID POKOK"]??"-")} &nbsp;•&nbsp;
        <b>Nama:</b> ${esc(x.p["NAMA POKOK"]||"-")} &nbsp;•&nbsp;
        <b>Petak:</b> ${esc(x.p.PETAK??"-")}
      </div>
    </div>`;
  }).join('');
}

async function saveUPSEditV47(){
  if(!upsCurrentFeatureV47)return;
  const f=upsCurrentFeatureV47, p=f.properties, uid=String(f.properties.UID);
  const next={
    "STATUS POKOK":valV47('u_STATUS'),
    "UMUR POKOK":valV47('u_AGE')===''?'':Number(valV47('u_AGE')),
    "LILITAN (cm)":valV47('u_CIRC')===''?'':Number(valV47('u_CIRC')),
    "DIAMETER (cm)":valV47('u_DIA')===''?'':Number(valV47('u_DIA')),
    "TINGGI_FINAL (m)":valV47('u_H')===''?'':Number(valV47('u_H')),
    "KAEDAH_TINGGI":valV47('u_METHOD'),
    "TARIKH TERIMA":valV47('u_DATE'),
    "HARGA PEROLEHAN ASAL":valV47('u_PRICE'),
    "ANGGARAN NILAI SEMASA":valV47('u_VALUE')
  };
  const norm=v=>v==null?'':String(v).trim();
  const changes={},before={};
  Object.keys(next).forEach(k=>{if(norm(p[k])!==norm(next[k])){before[k]=p[k];changes[k]=next[k];}});
  const state=document.getElementById('upsSaveStateV47');
  if(!Object.keys(changes).length){
    state.textContent='Tiada perubahan untuk disimpan';
    state.classList.remove('saved');
    return;
  }

  if(!window.supabaseClient) {
    state.textContent='✕ Sambungan Supabase tidak tersedia';
    state.classList.remove('saved');
    return;
  }

  try{
    state.textContent='Menyimpan ke Supabase…';
    state.classList.remove('saved');

    const {data,error}=await window.supabaseClient
      .from('pokok')
      .update({...changes,updated_at:new Date().toISOString()})
      .eq('UID',uid)
      .select('UID');

    if(error) throw error;
    if(!data || !data.length) throw new Error('Rekod tidak berjaya dikemas kini.');

    Object.assign(p,changes);

    const base=BASE_PROPS_V57[uid]||{};
    const editable=['STATUS POKOK','UMUR POKOK','LILITAN (cm)','DIAMETER (cm)','TINGGI_FINAL (m)','KAEDAH_TINGGI','TARIKH TERIMA','HARGA PEROLEHAN ASAL','ANGGARAN NILAI SEMASA'];
    const prospective={...p,...changes};
    const backToOriginal=editable.every(k=>norm(prospective[k])===norm(base[k]));

    if(backToOriginal){
      try{
        const saved=JSON.parse(localStorage.getItem(UPS_STORAGE_KEY_V47)||'{}'); delete saved[uid]; localStorage.setItem(UPS_STORAGE_KEY_V47,JSON.stringify(saved));
        [UPS_META_KEY_V48,UPS_META_KEY_V50,UPS_META_KEY_V55].forEach(key=>{const o=JSON.parse(localStorage.getItem(key)||'{}'); delete o[uid]; localStorage.setItem(key,JSON.stringify(o));});
      }catch(e){}
      UPDATED_UIDS_V51.delete(uid);
      state.textContent='✓ Data dikembalikan kepada data asal';
      state.classList.remove('saved');
    }else{
      saveUPSUpdateV47(f,changes);
      const now=new Date().toISOString();
      setUPSMetaV55(uid,{updatedAt:now,updatedFields:Object.keys(changes),before:before,after:{...changes}});
      UPDATED_UIDS_V51.add(uid);
      state.textContent='✓ Kemas kini disimpan • '+formatUpdatedAtV48(now);
      state.classList.add('saved');
      const meta=getUPSMetaV48(uid);
      document.getElementById('upsUpdateSummaryV48').innerHTML=`<div class="updated-row-v48"><span><b>✓ Kemas kini berjaya</b> • ${formatUpdatedAtV48(meta?.updatedAt)}</span><span>${Object.keys(changes).length} medan</span></div>`;
    }
    if(typeof render==='function')render();
    renderUPSHistoryV57();
    focusUPSMiniMapV48(f);
    if(typeof showInfo==='function' && currentFeature===f)showInfo(f);
  }catch(e){
    console.error('Supabase UPS update:',e);
    state.textContent='✕ Gagal simpan ke Supabase: '+(e?.message||e);
    state.classList.remove('saved');
  }
}
function cancelUPSEditV47(){
  if(upsCurrentFeatureV47) openUPSEditorV47(upsCurrentFeatureV47);
}
