function setMapUIVisible(show){
  const selectors=[
    '.map-search-v33',
    '.search-status-v33',
    '.advanced-filters',
    '.filter',
    '.legend',
    '.statusbar',
    '.leaflet-control-container',
    '#results',
    '#basemapMenuV42'
  ];
  selectors.forEach(sel=>{
    document.querySelectorAll(sel).forEach(el=>{
      el.style.visibility=show?'':'hidden';
      el.style.pointerEvents=show?'':'none';
    });
  });
}

function setMapSearchVisible(show){
  const ids=['.map-search-v33','.map-search-panel','.search'];
  ids.forEach(sel=>document.querySelectorAll(sel).forEach(el=>{
    if(el.closest('#aboutScreen')) return;
    if(el.classList.contains('search') && !el.closest('#map')) return;
    el.style.display=show?'':'none';
  }));
}

