function populateInventory(){
  const plots=[...new Set(all.map(f=>f.properties.PETAK).filter(v=>v!==null&&v!==""))].sort();
  document.getElementById('invPlot').innerHTML='<option value="">Semua Petak</option>'+plots.map(v=>`<option>${esc(v)}</option>`).join('');
}
function renderInventory(){
  const q=document.getElementById('invSearch').value.trim().toLowerCase();
  const pl=document.getElementById('invPlot').value;
  const st=document.getElementById('invStatus').value;
  const rows=all.filter(f=>{
    const p=f.properties;
    const t=[p.UID,p["ID POKOK"],p["NAMA POKOK"],p.PETAK].join(" ").toLowerCase();
    return (!q||t.includes(q))&&(!pl||String(p.PETAK)===pl)&&(!st||String(p["STATUS POKOK"])===st);
  });
  document.getElementById('invBody').innerHTML=rows.map(f=>{
    const p=f.properties;
    return `<tr data-uid="${esc(p.UID)}">
      <td>${esc(p.UID)}</td><td>${esc(p["ID POKOK"])}</td><td>${esc(p.PETAK)}</td>
      <td>${esc(p["NAMA POKOK"])}</td><td>${esc(p["STATUS POKOK"])}</td>
      <td>${esc(p["UMUR POKOK"]??"-")}</td><td>${esc(p["TARIKH TERIMA"]??"-")}</td>
      <td>${esc(p["HARGA PEROLEHAN ASAL"]??"-")}</td><td>${esc(p["ANGGARAN NILAI SEMASA"]??"-")}</td>
      <td>${num(p["DIAMETER (cm)"])}</td><td>${num(p["TINGGI_FINAL (m)"])}</td>
      <td>${num(p["BERAT KERING (kg)"])}</td><td>${num(p["lb - kg"])}</td>
      <td>${num(p["CO₂ TERKUMPUL (kg CO₂)"])}</td>
      <td>${num(p["PURATA ANGGARAN SERAP CO₂ (kg/tahun)"])}</td></tr>`;
  }).join('');
  document.getElementById('invCount').textContent=rows.length.toLocaleString('en-MY')+" rekod";
  document.querySelectorAll('#invBody tr').forEach(tr=>{
    tr.onclick=()=>{
      const f=all.find(x=>x.properties.UID===tr.dataset.uid);
      if(f){showMap();showInfo(f);}
    };
  });
}
function showInventory(){
  if(typeof closeInfo==='function')closeInfo();
  homeScreenEl.style.display='none';
  mapEl.style.display='none';
  inventoryScreen.classList.add('show');
  document.querySelectorAll('.nav').forEach(n=>n.classList.remove('active'));
  document.querySelectorAll('.nav')[1].classList.add('active');
  populateInventory();
  renderInventory();
}

