const analysisScreen=document.getElementById('analysisScreen');

function populateAnalysisFilters(){
  const plots=[...new Set(all.map(f=>f.properties.PETAK).filter(Boolean))].sort();
  const methods=[...new Set(all.map(f=>f.properties["KAEDAH_TINGGI"]).filter(Boolean))].sort();
  const species=[...new Set(all.map(f=>f.properties["NAMA POKOK"]).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  anPlot.innerHTML='<option value="">Semua Petak</option>'+plots.map(v=>`<option>${esc(v)}</option>`).join('');
  anMethod.innerHTML='<option value="">Semua Kaedah</option>'+methods.map(v=>`<option>${esc(v)}</option>`).join('');
  anSpecies.innerHTML='<option value="">Semua Spesies</option>'+species.map(v=>`<option>${esc(v)}</option>`).join('');
}
function analysisRows(){
  const pl=anPlot.value, st=anStatus.value, me=anMethod.value, sp=anSpecies.value;
  return all.filter(f=>{
    const p=f.properties;
    return (!pl||String(p.PETAK)===pl)&&(!st||String(p["STATUS POKOK"])===st)&&(!me||String(p["KAEDAH_TINGGI"])===me)&&(!sp||String(p["NAMA POKOK"])===sp);
  });
}
function fmtA(v){return Number(v||0).toLocaleString('en-MY',{maximumFractionDigits:2});}
function makeBarA(id,labels,vals){
  const box=document.getElementById(id),max=Math.max(...vals,1);
  box.innerHTML=labels.map((l,i)=>`<div class="bar-row-v2"><div class="bar-label-v2">${esc(l)}</div><div class="bar-track-v2"><div class="bar-fill-v2" style="width:${vals[i]/max*100}%"></div></div><div class="bar-val-v2">${fmtA(vals[i])}</div></div>`).join('');
}
function fmt3V84(v){return Number(v||0).toLocaleString('en-MY',{minimumFractionDigits:3,maximumFractionDigits:3});}
function updatePetakAnalysisV84(){
  updatePetakAnalysisV88();
  const rows=petakDataV84.map(f=>f.properties||{}).filter(p=>p.PETAK);
  const areaTotal=rows.reduce((s,p)=>s+(Number(p.Luas_Ha)||0),0);
  const largest=rows.slice().sort((a,b)=>(Number(b.Luas_Ha)||0)-(Number(a.Luas_Ha)||0))[0]||null;
  const densest=rows.slice().sort((a,b)=>(Number(b.Kepadatan)||0)-(Number(a.Kepadatan)||0))[0]||null;
  const totalEl=document.getElementById('petakTotalV84');
  const areaEl=document.getElementById('petakAreaTotalV84');
  const largestEl=document.getElementById('petakLargestV84');
  const largestSub=document.getElementById('petakLargestSubV84');
  const densestEl=document.getElementById('petakDensestV84');
  const densestSub=document.getElementById('petakDensestSubV84');
  if(totalEl) totalEl.textContent=rows.length;
  if(areaEl) areaEl.textContent=areaTotal.toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2});
  if(largestEl) largestEl.textContent=largest?`${Number(largest.Luas_Ha).toFixed(2)} ha`:'-';
  if(largestSub) largestSub.textContent=largest?`Petak ${esc(largest.PETAK)}`:'-';
  if(densestEl) densestEl.textContent=densest?`${fmt3V84(densest.Kepadatan)} pokok/ha`:'-';
  if(densestSub) densestSub.textContent=densest?`Petak ${esc(densest.PETAK)}`:'-';

  const areaBox=document.getElementById('petakAreaChartV84');
  const densBox=document.getElementById('petakDensityChartV84');
  const tableBox=document.getElementById('petakTableV84');
  const areaRows=rows.slice().sort((a,b)=>(Number(b.Luas_Ha)||0)-(Number(a.Luas_Ha)||0));
  const densRows=rows.slice().sort((a,b)=>(Number(b.Kepadatan)||0)-(Number(a.Kepadatan)||0));
  const maxA=Math.max(...areaRows.map(p=>Number(p.Luas_Ha)||0),1);
  const maxD=Math.max(...densRows.map(p=>Number(p.Kepadatan)||0),1);
  if(areaBox) areaBox.innerHTML=areaRows.map(p=>{
    const v=Number(p.Luas_Ha)||0;
    return `<div class="petak-bar-row-v84"><div class="petak-bar-label-v84">${esc(p.PETAK)}</div><div class="petak-bar-track-v84"><div class="petak-bar-fill-v84" style="width:${v/maxA*100}%"></div></div><div class="petak-bar-val-v84">${v.toFixed(2)} ha</div></div>`;
  }).join('');
  if(densBox) densBox.innerHTML=densRows.map(p=>{
    const v=Number(p.Kepadatan)||0;
    return `<div class="petak-bar-row-v84"><div class="petak-bar-label-v84">${esc(p.PETAK)}</div><div class="petak-bar-track-v84"><div class="petak-bar-fill-v84" style="width:${v/maxD*100}%"></div></div><div class="petak-bar-val-v84">${fmt3V84(v)}</div></div>`;
  }).join('');
  if(tableBox) tableBox.innerHTML=`<table class="petak-table-v84"><thead><tr><th>Petak</th><th>Luas (ha)</th><th>Pokok</th><th>Kepadatan (pokok/ha)</th></tr></thead><tbody>`+
    rows.slice().sort((a,b)=>String(a.PETAK).localeCompare(String(b.PETAK))).map(p=>`<tr><td><span class="petak-tag-v84">${esc(p.PETAK)}</span></td><td class="num">${Number(p.Luas_Ha).toFixed(2)}</td><td class="num">${Number(p.NUMPOINTS||0).toLocaleString('en-MY')}</td><td class="num">${fmt3V84(p.Kepadatan)}</td></tr>`).join('')+
    `</tbody></table>`;
}
function updateAnalysis(){
  const rows=analysisRows(), plots=['A','B','C','D','E','F','G','H','I','J','K','L','M','N','O','P'];
  const live=rows.filter(f=>String(f.properties["STATUS POKOK"])==="HIDUP").length;
  const dead=rows.filter(f=>String(f.properties["STATUS POKOK"])==="MATI").length;
  const sum=k=>rows.reduce((s,f)=>s+(Number(f.properties[k])||0),0);
  const bio=sum("BERAT KERING (kg)"), carbon=sum("lb - kg"), co2=sum("CO₂ TERKUMPUL (kg CO₂)");
  anTotal.textContent=rows.length.toLocaleString('en-MY');
  anLive.textContent=live.toLocaleString('en-MY'); anDead.textContent=dead.toLocaleString('en-MY');
  anBio.textContent=fmtA(bio)+" kg"; anCarbon.textContent=fmtA(carbon)+" kg"; anCO2.textContent=fmtA(co2)+" kg";
  const lp=rows.length?live/rows.length*100:0;
  statusDonut.style.background=`conic-gradient(#19bb50 0 ${lp}%, #e53935 ${lp}% 100%)`;
  statusCenter.textContent=rows.length.toLocaleString('en-MY');
  statusLegend.innerHTML=`<div><span class="legend-dot" style="background:#19bb50"></span>HIDUP — <b>${live}</b> (${lp.toFixed(2)}%)</div><div><span class="legend-dot" style="background:#e53935"></span>MATI — <b>${dead}</b> (${(100-lp).toFixed(2)}%)</div>`;

  const counts=plots.map(pl=>rows.filter(f=>String(f.properties.PETAK)===pl).length);
  makeBarA('plotChartV2',plots,counts);

  const bioVals=plots.map(pl=>rows.filter(f=>String(f.properties.PETAK)===pl).reduce((s,f)=>s+(Number(f.properties["BERAT KERING (kg)"])||0),0));
  const carbonVals=plots.map(pl=>rows.filter(f=>String(f.properties.PETAK)===pl).reduce((s,f)=>s+(Number(f.properties["lb - kg"])||0),0));
  const maxBoth=Math.max(...bioVals,...carbonVals,1);
  bioCarbonChartV2.innerHTML=plots.map((pl,i)=>`<div class="dual-row-v2"><div class="bar-label-v2">${pl}</div><div class="dual-bars"><div class="mini-track"><div class="mini-fill-bio" style="width:${bioVals[i]/maxBoth*100}%"></div></div><div class="mini-track"><div class="mini-fill-carbon" style="width:${carbonVals[i]/maxBoth*100}%"></div></div></div><div class="bar-val-v2">${fmtA(bioVals[i])}</div></div>`).join('');

  const co2Vals=plots.map(pl=>rows.filter(f=>String(f.properties.PETAK)===pl).reduce((s,f)=>s+(Number(f.properties["CO₂ TERKUMPUL (kg CO₂)"])||0),0));
  makeBarA('co2ChartV2',plots,co2Vals);

  const freq={}; rows.forEach(f=>{const s=f.properties["NAMA POKOK"]||"Tidak Diketahui";freq[s]=(freq[s]||0)+1});
  const top=Object.entries(freq).sort((a,b)=>b[1]-a[1]).slice(0,10), maxS=Math.max(...top.map(x=>x[1]),1);
  speciesChartV2.innerHTML=top.length?top.map(([s,n])=>`<div class="species-row"><div class="lab">${esc(s)}</div><div class="bar-track-v2"><div class="bar-fill-v2" style="width:${n/maxS*100}%"></div></div><div class="bar-val-v2">${n}</div></div>`).join(''):'<div style="color:#6b7b74">Tiada data.</div>';

  const topPetak=plots.map((p,i)=>[p,counts[i]]).sort((a,b)=>b[1]-a[1])[0]||['-',0], topSpecies=top[0]||['-',0];
  analysisSummaryV2.innerHTML=[
    ['Petak tertinggi',`${topPetak[0]} (${topPetak[1]} pokok)`],['Spesies tertinggi',`${topSpecies[0]} (${topSpecies[1]} pokok)`],
    ['Biomassa',`${fmtA(bio)} kg`],['Karbon',`${fmtA(carbon)} kg`],['CO₂ terkumpul',`${fmtA(co2)} kg`],
    ['CO₂ / tahun',`${fmtA(sum("PURATA ANGGARAN SERAP CO₂ (kg/tahun)"))} kg/tahun`]
  ].map(x=>`<div class="summary-item"><div class="a">${esc(x[0])}</div><div class="b">${esc(x[1])}</div></div>`).join('');
}
function showAnalysis(){
  if(typeof closeInfo==='function')closeInfo();
  homeScreenEl.style.display='none';
  inventoryScreen.classList.remove('show');
  analysisScreen.style.display='block';
  mapEl.style.display='none';
  document.querySelectorAll('.nav').forEach(n=>n.classList.remove('active'));
  document.querySelectorAll('.nav')[2].classList.add('active');
  populateAnalysisFilters();
  if(selectedPetakV88){ const ae=document.getElementById('anPlot'); if(ae && [...ae.options].some(o=>o.value===selectedPetakV88)) ae.value=selectedPetakV88; }
  updatePetakAnalysisV84();
  updateAnalysis();
  window.scrollTo(0,0);
}



