function resetMapV45(){
  // Keep existing Reset search behavior, then also clear advanced filters.
  document.getElementById('searchInput').value='';
  document.getElementById('searchField').value='';
  document.getElementById('plot').value='';
  document.getElementById('status').value='';
  ['advPlot','advStatus','advMethod','advSpecies'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  ['advMinDia','advMaxDia','advMinHeight','advMaxHeight'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  const af=document.getElementById('advancedFilters'); if(af) af.style.display='none';
  const resultEl=document.getElementById('results'); if(resultEl) resultEl.style.display='none';
  if(typeof closeInfo==='function') closeInfo();
  clearPetakSearchCardV86();
  selectedPetakV88=''; updatePetakAnalysisV88(); updateAnalysis();
  render();
  if(all.length){
    const bounds=L.latLngBounds(all.map(f=>xy(f)));
    map.fitBounds(bounds.pad(.05));
  }
}
