function updateSearchStatusV33(){
  const el=document.getElementById('searchStatusV33');
  if(!el)return;
  const q=document.getElementById('searchInput').value.trim();
  const f=document.getElementById('searchField').value;
  const rows=filtered();
  if(!q && !document.getElementById('plot').value && !document.getElementById('status').value){
    el.textContent="Semua 1,123 rekod dipaparkan";
  }else{
    const labels={PETAK:"Petak","STATUS POKOK":"Status",KAEDAH_TINGGI:"Kaedah Tinggi","ID POKOK":"ID Pokok","NAMA POKOK":"Nama Pokok"};
    el.textContent=(f?labels[f]:"Carian")+": "+(q||"—")+" • "+rows.length.toLocaleString('en-MY')+" rekod";
  }
}


