/* Same-browser sync: if another open copy of this Web GIS updates a record,
   this copy receives it immediately. No navigation events are intercepted. */
window.addEventListener('storage',e=>{
  if(e.key!=='pmm_ups_last_sync_v53'||!e.newValue) return;
  try{
    const msg=JSON.parse(e.newValue);
    const f=all.find(x=>String(x.properties.UID)===String(msg.uid));
    if(!f) return;
    Object.assign(f.properties,msg.changes||{});
    UPDATED_UIDS_V51.add(String(msg.uid));
    if(typeof render==='function') render();
    if(typeof currentFeature!=='undefined' && currentFeature===f && typeof showInfo==='function') showInfo(f);
  }catch(err){}
});


window.addEventListener('resize',()=>{const m=document.getElementById('basemapMenuV42');if(m&&m.style.display==='block')positionBasemapMenuV57();});

window.addEventListener('storage',e=>{
  if(e.key==='pmm_ups_last_sync_v57'){
    try{
      const m=JSON.parse(e.newValue||'{}');
      loadUPSUpdatesV47();
      UPDATED_UIDS_V51.add(String(m.uid||''));
      render();
      renderUPSHistoryV57();
    }catch(err){}
  }
});
