(function(){
  const PASSWORD="PMM2026";
  let unlocked=false;
  const overlay=document.getElementById("v79PasswordOverlay");
  const input=document.getElementById("v79PasswordInput");
  const error=document.getElementById("v79PasswordError");
  const ok=document.getElementById("v79PasswordOk");
  const cancel=document.getElementById("v79PasswordCancel");

  window.requireUPSAccessV79=function(cb){
    if(unlocked){ cb(); return; }
    overlay.style.display="flex";
    input.value="";
    error.style.display="none";
    setTimeout(()=>input.focus(),50);
    const submit=()=>{
      if(input.value===PASSWORD){
        unlocked=true;
        overlay.style.display="none";
        cb();
      }else{
        error.style.display="block";
        input.select();
      }
    };
    ok.onclick=submit;
    input.onkeydown=e=>{if(e.key==="Enter")submit();};
    cancel.onclick=()=>overlay.style.display="none";
  };
})();
